files.content:
.btn{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:var(--s-2);
  font-family:var(--font-sans);
  font-size:var(--t-body);
  font-weight:500;
  letter-spacing:var(--tr-snug);
  line-height:1;
  min-height:var(--s-10);
  padding:0 var(--s-6);
  border-radius:var(--r-full);
  transition:all var(--d-quick) var(--ease-standard);
  border:var(--bw-1) solid transparent;
  white-space:nowrap;
}
.btn-floating{
  display:flex;
  width:max-content;
  position:sticky;
  top:var(--float-top, var(--s-4));
  z-index:var(--z-sticky);
  margin-bottom:calc(-1 * var(--s-10));
  padding:0 var(--s-5) 0 var(--s-4);
  font-size:var(--t-small);
  background:var(--surface-glass);
  border-color:var(--border);
  color:var(--obsidian-100);
  backdrop-filter:blur(var(--blur-glass));
}
.btn-floating:hover{
  border-color:var(--border-strong);
}
.btn:disabled{
  opacity:0.4;
  cursor:not-allowed;
}
.btn-primary{
  background:var(--primary-500);
  color:var(--obsidian-050);
  border-color:var(--primary-500);
  box-shadow:var(--sh-2);
  transition:all var(--d-quick) var(--ease-standard), transform var(--d-quick) var(--ease-spring);
}
.btn-primary:hover{
  background:var(--primary-500);
  color:var(--obsidian-050);
  border-color:var(--primary-500);
  box-shadow:var(--sh-glow), var(--sh-3);
}
.btn-secondary{
  background:var(--obsidian-800);
  color:var(--obsidian-100);
  border-color:var(--obsidian-700);
}
.btn-secondary:hover{
  background:var(--obsidian-700);
  border-color:var(--obsidian-600);
}
.btn-ghost{
  color:var(--obsidian-100);
  background:transparent;
}
.btn-ghost:hover{
  background:var(--obsidian-800);
}
.btn-outline{
  background:transparent;
  color:var(--obsidian-100);
  border-color:var(--obsidian-600);
}
.btn-outline:hover{
  border-color:var(--primary-500);
  color:var(--primary-400);
}
.btn-danger{
  background:var(--danger);
  color:var(--obsidian-950);
}
.btn-danger:hover{
  filter:brightness(1.05);
}
.btn-primary:active:not(:disabled){
  background:var(--primary-600);
  border-color:var(--primary-600);
  box-shadow:var(--sh-1);
  transform:scale(.97);
}
.btn-secondary:active:not(:disabled){
  background:var(--obsidian-600);
  border-color:var(--obsidian-500);
}
.btn-ghost:active:not(:disabled){
  background:var(--obsidian-700);
}
.btn-outline:active:not(:disabled){
  border-color:var(--primary-600);
  color:var(--primary-500);
}
.btn-danger:active:not(:disabled){
  filter:none;
  background:color-mix(in srgb, var(--danger) 85%, var(--obsidian-950));
}
.btn-floating:active:not(:disabled){
  border-color:var(--obsidian-500);
}
@media (prefers-reduced-motion: reduce){
  .btn-primary:active:not(:disabled){
    transform:none;
  }
}
.btn-sm{
  min-height:var(--s-8);
  padding:0 var(--s-4);
  font-size:var(--t-small);
}
.btn-lg{
  min-height:var(--s-12);
  padding:0 var(--s-8);
}
.btn-icon{
  width:var(--s-10);
  padding:0;
}
.btn-sm.btn-icon{
  width:var(--s-8);
}
.btn-lg.btn-icon{
  width:var(--s-12);
}
@media (pointer:coarse){
  .btn:not(.btn-lg){
    min-height:var(--target-touch);
  }
  .btn-icon:not(.btn-lg){
    min-width:var(--target-touch);
  }
}
.btn:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--focus-offset);
  box-shadow:var(--ring-halo);
}
